	open fun modpulsSolve(n: Int, x: cpp.PtrD?, xOld: cpp.PtrD?, xPrev: cpp.PtrD?, xMin: cpp.PtrD?, xMax: cpp.PtrD?, xTol: cpp.PtrD?, qOld: cpp.PtrD?, q: cpp.PtrD?, dt: Double, omega: Double): Int {
