				(x!!.ref_Item_i(i_2))!!.set(cpp.M.max_d_d(x!!.get_Item_i(i_2) as Double, xMin!!.get_Item_i(i_2) as Double))
				if ((omega > 0.0) && (cpp.SysMath.Abs_d((x!!.get_Item_i(i_2) as Double) - (xPrev!!.get_Item_i(i_2) as Double)) > (xTol!!.get_Item_i(i_2) as Double))) {
					canStop = 0
				}
				(xPrev!!.ref_Item_i(i_2))!!.set(x!!.get_Item_i(i_2) as Double)
				i_2++
			}
			if (canStop != 0) {
				return steps
			}
			steps++
		}
		return 0
	}

